package com.univmar.quotation.domain;
import jakarta.persistence.*; import java.math.*; import java.util.*;
@Entity @Table(name="quotation_item") public class QuotationItem { @Id private UUID id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="quotation_id") private Quotation quotation; @Column(name="variant_id") private UUID variantId; @Column(name="material_name",nullable=false,length=180) private String materialName; @Column(name="variant_label",nullable=false,length=220) private String variantLabel; @Column(name="quantity_m2",nullable=false,precision=14,scale=3) private BigDecimal quantityM2; @Column(name="unit_price",nullable=false,precision=14,scale=2) private BigDecimal unitPrice; @Column(name="discount_percent",nullable=false,precision=5,scale=2) private BigDecimal discountPercent; @Column(name="tax_percent",nullable=false,precision=5,scale=2) private BigDecimal taxPercent; protected QuotationItem(){} public QuotationItem(Quotation q,String m,String v,BigDecimal qty,BigDecimal price,BigDecimal discount,BigDecimal tax){this(q,null,m,v,qty,price,discount,tax);} public QuotationItem(Quotation q,UUID variant,String m,String v,BigDecimal qty,BigDecimal price,BigDecimal discount,BigDecimal tax){id=UUID.randomUUID();quotation=q;variantId=variant;materialName=m;variantLabel=v;quantityM2=qty;unitPrice=price;discountPercent=discount;taxPercent=tax;} public BigDecimal net(){return quantityM2.multiply(unitPrice).multiply(BigDecimal.ONE.subtract(discountPercent.movePointLeft(2))).setScale(2,RoundingMode.HALF_UP);} public BigDecimal tax(){return net().multiply(taxPercent.movePointLeft(2)).setScale(2,RoundingMode.HALF_UP);} public UUID getId(){return id;} public UUID getVariantId(){return variantId;} public String getMaterialName(){return materialName;} public String getVariantLabel(){return variantLabel;} public BigDecimal getQuantityM2(){return quantityM2;} public BigDecimal getUnitPrice(){return unitPrice;} public BigDecimal getDiscountPercent(){return discountPercent;} public BigDecimal getTaxPercent(){return taxPercent;} }
